use crate::gf2p8lut::{Gf2p8Lut, SubspaceBasisLut};
use additive_fft_reed_solomon_gf2p8::{FIELD_SIZE, Gf2p8, Gf2p8_11d, Z255};

pub mod generated {
    // Include the constants generated by build.rs
    include!(concat!(env!("OUT_DIR"), "/tables_11d.rs"));

    pub mod cantor {
        include!(concat!(env!("OUT_DIR"), "/poly_11d_cantor.rs"));
    }

    pub mod standard {
        include!(concat!(env!("OUT_DIR"), "/poly_11d_standard.rs"));
    }
}

impl Gf2p8Lut for Gf2p8_11d {
    fn mul_lut(self, other: Self) -> Self {
        if self.0 == 0 || other.0 == 0 {
            return 0u8.into();
        }
        let self_log = generated::LOG_TABLE[self.0 as usize] as usize;
        let other_log = generated::LOG_TABLE[other.0 as usize] as usize;
        generated::EXP_TABLE[self_log + other_log].into()
    }

    fn inv_lut(self) -> Self {
        generated::INV_TABLE[self.into_usize()].into()
    }

    fn gfni_mul_matrix_lut(self) -> u64 {
        generated::GFNI_MUL_TABLE[self.into_usize()]
    }

    fn nibble_mul_table_lut(self) -> ([u8; 16], [u8; 16]) {
        generated::NIBBLE_MUL_TABLE[self.into_usize()]
    }
}

#[derive(Copy, Clone, Debug, Default, PartialEq)]
pub struct CantorBasisLut11d;

impl SubspaceBasisLut<Gf2p8_11d> for CantorBasisLut11d {
    const UNIT_DERIVS: bool = true;

    fn get_basis_point_lut(i: u8) -> Gf2p8_11d {
        generated::cantor::BASIS[i as usize].into()
    }

    fn get_subspace_point_lut(i: u8) -> Gf2p8_11d {
        generated::cantor::SUBSPACE[i as usize].into()
    }

    fn eval_subspace_poly_lut(k: u8, x: Gf2p8_11d) -> Gf2p8_11d {
        generated::cantor::SUBSPACE_POLY_VALUES[k as usize][x.into_usize()].into()
    }

    fn log_walsh_lut() -> &'static [Z255; FIELD_SIZE] {
        unsafe { &*(&generated::cantor::LOG_WALSH_TABLE as *const _ as *const [Z255; FIELD_SIZE]) }
    }

    fn subspace_poly_deriv_lut() -> &'static [Gf2p8_11d; 8] {
        unsafe { &*(&generated::cantor::SUBSPACE_POLY_DERIVS as *const _ as *const [Gf2p8_11d; 8]) }
    }
}

#[derive(Copy, Clone, Debug, Default, PartialEq)]
pub struct StandardBasisLut11d;

impl SubspaceBasisLut<Gf2p8_11d> for StandardBasisLut11d {
    const UNIT_DERIVS: bool = false;

    fn get_basis_point_lut(i: u8) -> Gf2p8_11d {
        generated::standard::BASIS[i as usize].into()
    }

    fn get_subspace_point_lut(i: u8) -> Gf2p8_11d {
        generated::standard::SUBSPACE[i as usize].into()
    }

    fn eval_subspace_poly_lut(k: u8, x: Gf2p8_11d) -> Gf2p8_11d {
        generated::standard::SUBSPACE_POLY_VALUES[k as usize][x.into_usize()].into()
    }

    fn log_walsh_lut() -> &'static [Z255; FIELD_SIZE] {
        unsafe {
            &*(&generated::standard::LOG_WALSH_TABLE as *const _ as *const [Z255; FIELD_SIZE])
        }
    }

    fn subspace_poly_deriv_lut() -> &'static [Gf2p8_11d; 8] {
        unsafe {
            &*(&generated::standard::SUBSPACE_POLY_DERIVS as *const _ as *const [Gf2p8_11d; 8])
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::poly_11d_lut::generated::{cantor, standard};
    use crate::poly_arith::{CantorBasisPolyArith, PolySliceArith};
    use additive_fft_reed_solomon_gf2p8::{CantorBasis11d, FIELD_SIZE, SubspaceBasis};

    #[test]
    fn mul_lut_correctness() {
        let a: Gf2p8_11d = 0x42.into();
        let b = 0x13.into();
        let expected = a.mul(b);
        let actual = a.mul_lut(b);

        assert_eq!(actual, expected);
    }

    #[test]
    fn gfni_mul_matrix_correctness() {
        let elems = || (0..FIELD_SIZE).map(|i| Gf2p8_11d::from(i as u8));
        for a in elems() {
            for b in elems() {
                let expected = a.mul(b);

                let mat = a.into_mul_matrix();
                let actual: u8 = mat.apply(b.into());

                assert_eq!(actual, u8::from(expected));
            }
        }
    }

    #[test]
    fn poly_mul_lnh_sum_of_degrees() {
        const DEGREE_A: usize = 3;
        const DEGREE_B: usize = 5;

        let basis = CantorBasisLut11d;

        let mut a = [0.into(); FIELD_SIZE];
        a[DEGREE_A] = 1.into();

        let mut b = [0.into(); FIELD_SIZE];
        b[DEGREE_B] = 1.into();

        let result = basis.poly_mul_lnh(&a, &b);

        assert_eq!(result.degree().unwrap(), DEGREE_A + DEGREE_B);
    }

    #[test]
    fn subspace_poly_trace() {
        let p2: Vec<u8> = (0..8).map(|i| 2u8.pow(i)).collect();

        let points: Vec<_> = p2
            .iter()
            .map(|&p| u8::from(CantorBasisLut11d::get_subspace_point_lut(p)))
            .collect();
        assert_eq!(points, [1, 214, 152, 146, 86, 200, 88, 231]);
    }

    #[test]
    fn normalization_factors_id() {
        let basis = CantorBasis11d::new();
        let subpoly_luts = basis.gen_all_subspace_poly_luts();
        let norm_factors = basis.gen_normalization_factors(&subpoly_luts, &generated::INV_TABLE);
        assert_eq!(norm_factors, [1u8; 256]);
    }

    #[test]
    fn unit_derivs_correct() {
        let all_one = |d: [u8; 8]| d.iter().all(|c| *c == 1);
        assert_eq!(
            CantorBasisLut11d::UNIT_DERIVS,
            all_one(cantor::SUBSPACE_POLY_DERIVS)
        );
        assert_eq!(
            StandardBasisLut11d::UNIT_DERIVS,
            all_one(standard::SUBSPACE_POLY_DERIVS)
        );
    }
}

